{"content":"#!/usr/bin/env python3
"""Minesweeper safest-move solver (16x16, no flag info, total mines assumed 40)."""
import sys
from collections import deque

N = 16
TOTAL_MINES = 40  # standard 16x16 intermediate count; used only for background estimate


def parse_board(path):
    try:
        with open(path, "r") as f:
            raw_lines = [ln.rstrip("\n") for ln in f]
    except OSError:
        return None
    # drop fully empty lines at end (but keep structure)
    # keep non-empty lines; if file has blank lines interspersed -> invalid
    lines = [ln for ln in raw_lines if ln.strip() != ""]
    if len(lines) != N:
        return None
    board = []
    for ln in lines:
        parts = ln.split()
        if len(parts) == N:
            row = parts
        elif len(parts) == 1 and len(parts[0]) == N:
            row = list(parts[0])
        else:
            # try chars without spaces but with possible no split? invalid
            return None
        for ch in row:
            if ch == "." or (len(ch) == 1 and ch.isdigit() and 0 <= int(ch) <= 8):
                continue
            return None
        board.append(row)
    if len(board) != N or any(len(r) != N for r in board):
        return None
    return board


def neighbors(r, c):
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc


def solve():
    board = parse_board("/app/board.txt")
    out = "/app/safe_move.txt"

    def write(s):
        with open(out, "w") as f:
            f.write(s)

    if board is None:
        write("-1,-1")
        return

    hidden = [(r, c) for r in range(N) for c in range(N) if board[r][c] == "."]
    if not hidden:
        write("-1,-1")
        return

    # Build constraints: for each revealed number, sum over adjacent hidden == value
    constraints = []  # list of (value, [vars])
    for r in range(N):
        for c in range(N):
            if board[r][c] != ".":
                v = int(board[r][c])
                adj_hidden = [(nr, nc) for (nr, nc) in neighbors(r, c) if board[nr][nc] == "."]
                if v < 0 or v > len(adj_hidden):
                    write("-1,-1")
                    return
                # constraint with zero hidden vars is fine (v must be 0, checked above)
                if adj_hidden:
                    constraints.append((v, adj_hidden))
                else:
                    if v != 0:
                        # e.g. a '1' with no hidden neighbors but also no flags -> impossible
                        # Actually if all neighbors revealed numbers, required mines = v > 0 impossible
                        write("-1,-1")
                        return

    frontier_set = set()
    for _, vs in constraints:
        frontier_set.update(vs)
    frontier = sorted(frontier_set)
    background = [cell for cell in hidden if cell not in frontier_set]

    if not frontier:
        # No information: all equal; return first hidden
        r, c = hidden[0]
        write(f"{r},{c}")
        return

    # Map var -> index
    var_index = {v: i for i, v in enumerate(frontier)}
    # Convert constraints to index lists
    cons_idx = []
    for v, vs in constraints:
        cons_idx.append((v, [var_index[x] for x in vs]))

    # Connected components over variables linked by shared constraint
    # Build adjacency var->vars via constraints
    adj = {i: set() for i in range(len(frontier))}
    for _, vs in cons_idx:
        for a in vs:
            for b in vs:
                if a != b:
                    adj[a].add(b)
    visited = [False] * len(frontier)
    # var component assignment; also gather component constraints
    components = []  # list of (var_list, con_list_indices)
    con_used = [False] * len(cons_idx)
    # constraint -> vars set for quick lookup
    for i in range(len(frontier)):
        if visited[i]:
            continue
        # BFS over vars
        q = deque([i])
        visited[i] = True
        comp_vars = set([i])
        while q:
            u = q.popleft()
            for w in adj[u]:
                if not visited[w]:
                    visited[w] = True
                    comp_vars.add(w)
                    q.append(w)
        # collect constraints touching this component
        comp_cons = []
        for ci, (_, vs) in enumerate(cons_idx):
            if any(v in comp_vars for v in vs):
                comp_cons.append(ci)
        components.append((sorted(comp_vars), comp_cons))

    # Enumerate each component
    prob = {}  # global var idx -> P(mine)
    comp_stats = []  # (avg_mines, min_mines, max_mines, nsolutions)
    LIMIT_SOLUTIONS = 200000

    for comp_vars, comp_cons in components:
        k = len(comp_vars)
        # local mapping global -> local 0..k-1
        g2l = {g: li for li, g in enumerate(comp_vars)}
        local_cons = []
        for ci in comp_cons:
            v, vs = cons_idx[ci]
            local_cons.append((v, [g2l[g] for g in vs]))
        # order vars by degree desc for pruning
        degree = [0] * k
        for _, vs in local_cons:
            for li in vs:
                degree[li] += 1
        order = sorted(range(k), key=lambda li: -degree[li])
        # reorder: pos_in_order -> local idx; also constraint var lists in terms of order positions
        l2o = {li: oi for oi, li in enumerate(order)}
        o_cons = []
        for v, vs in local_cons:
            o_cons.append((v, [l2o[li] for li in vs]))
        # For pruning, precompute for each constraint the member order positions set
        # Backtrack
        assign = [-1] * k  # by order position
        # constraint state: for fast check, evaluate incrementally
        # Precompute members per constraint
        mine_count = [0] * k  # per order position
        nsol = 0
        tot_mines_sum = 0
        # To prune efficiently: after assigning prefix [0..pos], for each constraint check feasibility
        # Build var->constraints map
        var_cons = [[] for _ in range(k)]
        for ci, (_, vs) in enumerate(o_cons):
            for oi in vs:
                var_cons[oi].append(ci)

        # If component too large, fall back to heuristic (deduction + sampling)
        use_fallback = k > 32

        if not use_fallback:
            # iterative stack to avoid recursion limits
            # Use recursive DFS with pruning; k<=32 fine
            sys.setrecursionlimit(10000)
            too_many = [False]

            def feasible(pos):
                # check all constraints involving assigned vars up to pos
                # full check of every constraint each time is O(C*k) but k small
                for v, vs in o_cons:
                    s = 0
                    u = 0
                    for oi in vs:
                        a = assign[oi]
                        if a == 1:
                            s += 1
                        elif a == -1:
                            u += 1
                    if s > v or s + u < v:
                        return False
                return True

            def dfs(pos):
                nonlocal nsol, tot_mines_sum
                if too_many[0]:
                    return
                if pos == k:
                    nsol += 1
                    tot_mines_sum += sum(assign)
                    for oi in range(k):
                        if assign[oi] == 1:
                            mine_count[oi] += 1
                    if nsol >= LIMIT_SOLUTIONS:
                        # stop counting exactly; mark approximate (cap)
                        # continue? stop to save time -> switch to sampling mode is complex;
                        # just stop and use current counts as estimate
                        too_many[0] = True
                    return
                for val in (0, 1):
                    assign[pos] = val
                    if feasible(pos):
                        dfs(pos + 1)
                        if too_many[0]:
                            assign[pos] = -1
                            return
                    assign[pos] = -1

            dfs(0)
            if nsol == 0:
                write("-1,-1")
                return
            # record probs (map back to global)
            for oi, li in enumerate(order):
                g = comp_vars[li]
                prob[g] = mine_count[oi] / nsol
            avg_m = tot_mines_sum / nsol
            comp_stats.append((avg_m, nsol))
        else:
            # Fallback for large component: try pure-logic deduction + local estimate.
            # 1) Check single-constraint determined cells.
            # 2) Estimate prob via repeated random sampling with repair (rejection sampling).
            import random
            random.seed(0)
            # Build quick deduction: if any constraint v==0 -> all safe; v==len -> all mines
            determined_mine = set()
            determined_safe = set()
            for v, vs in o_cons:
                if v == 0:
                    for oi in vs:
                        determined_safe.add(oi)
                elif v == len(vs):
                    for oi in vs:
                        determined_mine.add(oi)
            # rejection sampling: sample uniform random assignments, keep valid ones
            # bias toward satisfying: sample each var with p = avg constraint density
            tot_v = sum(v for v, _ in o_cons)
            tot_slots = sum(len(vs) for _, vs in o_cons)
            p0 = tot_v / tot_slots if tot_slots else 0.2
            p0 = min(max(p0, 0.05), 0.95)
            samples = 0
            max_samples = 20000
            target_valid = 5000
            valid = 0
            acc = [0] * k
            tot_m = 0
            # precompute member sets for fast validity
            cons_members = [(v, set(vs)) for v, vs in o_cons]
            trials = 0
            while valid < target_valid and trials < max_samples * 10:
                trials += 1
                a = [1 if random.random() < p0 else 0 for _ in range(k)]
                # force determined
                ok = True
                for oi in determined_mine:
                    if a[oi] != 1:
                        ok = False
                        break
                if not ok:
                    continue
                for oi in determined_safe:
                    if a[oi] != 0:
                        ok = False
                        break
                if not ok:
                    continue
                for v, vs in o_cons:
                    s = sum(a[oi] for oi in vs)
                    if s != v:
                        ok = False
                        break
                if ok:
                    valid += 1
                    tot_m += sum(a)
                    for oi in range(k):
                        acc[oi] += a[oi]
            if valid == 0:
                # sampling failed: use local heuristic probs (average of constraint ratios)
                # and check logical contradiction via subset rule below; assume satisfiable
                var_sum = [0.0] * k
                var_cnt = [0] * k
                for v, vs in o_cons:
                    r = v / len(vs) if vs else 0
                    for oi in vs:
                        var_sum[oi] += r
                        var_cnt[oi] += 1
                for oi in range(k):
                    g = comp_vars[order[oi]] if False else None
                for oi in range(k):
                    li = order[oi]
                    g = comp_vars[li]
                    prob[g] = (var_sum[oi] / var_cnt[oi]) if var_cnt[oi] else 0.2
                # rough avg
                avg_m = sum(prob[comp_vars[li]] for li in range(k))
                comp_stats.append((avg_m, 1))
                # still need satisfiability check: verify determined sets don't conflict
                for v, vs in o_cons:
                    # count forced
                    fm = sum(1 for oi in vs if oi in determined_mine)
                    fs = sum(1 for oi in vs if oi in determined_safe)
                    # remaining must be able to fill v
                    if fm > v or fm + (len(vs) - fm - fs) < v:
                        write("-1,-1")
                        return
            else:
                for oi in range(k):
                    li = order[oi]
                    g = comp_vars[li]
                    prob[g] = acc[oi] / valid
                comp_stats.append((tot_m / valid, valid))

    # Check for certain-safe frontier cells
    for g in sorted(prob):
        if prob[g] == 0.0:
            r, c = frontier[g]
            write(f"{r},{c}")
            return

    # No certain safe on frontier. Consider background.
    # Also subset-rule safe cells are already prob 0 via enumeration; nothing extra needed.

    # Find min frontier prob
    min_g = min(prob, key=lambda g: (prob[g], g))
    min_p = prob[min_g]

    if background:
        avg_frontier = sum(a for a, _ in comp_stats)
        fsize = len(frontier)
        bsize = len(background)
        if avg_frontier > TOTAL_MINES:
            # assumption violated: use frontier density as background estimate
            bg_p = avg_frontier / fsize if fsize else 1.0
        else:
            bg_p = (TOTAL_MINES - avg_frontier) / bsize
            bg_p = min(max(bg_p, 0.0), 1.0)
        if bg_p < min_p - 1e-12:
            # safest is background: pick background cell farthest from any revealed number
            # (all background cells are non-adjacent by construction; maximize distance for safety margin)
            revealed = [(r, c) for r in range(N) for c in range(N) if board[r][c] != "."]
            def mindist(cell):
                r, c = cell
                return min(abs(r - rr) + abs(c - cc) for rr, cc in revealed) if revealed else 99
            best = max(background, key=lambda cell: (mindist(cell), -cell[0], -cell[1]))
            write(f"{best[0]},{best[1]}")
            return
        elif abs(bg_p - min_p) <= 1e-12:
            # tie: prefer certain background? any is fine; return background far cell
            # (still a correct answer since tied). Keep frontier choice to be deterministic?
            # Prefer background when tied? Either acceptable. Choose background for real-game safety.
            revealed = [(r, c) for r in range(N) for c in range(N) if board[r][c] != "."]
            def mindist(cell):
                r, c = cell
                return min(abs(r - rr) + abs(c - cc) for rr, cc in revealed) if revealed else 99
            best = max(background, key=lambda cell: (mindist(cell), -cell[0], -cell[1]))
            # Only prefer background if it is truly tied; either is correct.
            write(f"{best[0]},{best[1]}")
            return
    # otherwise safest is frontier min
    r, c = frontier[min_g]
    write(f"{r},{c}")


if __name__ == "__main__":
    solve()
