{"content":"#!/usr/bin/env python3
"""Minesweeper safest-move solver for a 16x16 board.

Reads /app/board.txt ('.' hidden, '0'-'8' revealed), writes the safest
unrevealed cell as 'row,col' to /app/safe_move.txt (or '-1,-1' when no
unrevealed cell exists or the input is malformed / locally impossible).

Method:
  * Build one exact-cover constraint per revealed number:
        sum(hidden neighbours) == number
    (there are no flags, so revealed neighbours can never be mines).
  * Split the frontier into connected components and enumerate every
    satisfying mine placement per component (exact, with pruning).
  * A cell with mine probability 0 in all solutions is returned.
  * Otherwise the frontier cell with the lowest exact probability is
    compared against uninformative background cells, whose probability is
    estimated from the standard 16x16 total of 40 mines, and the global
    minimum is returned.
  * If the constraints are individually fine but admit no global solution
    (only possible for a board that could never arise from a real game),
    fall back to best-effort local deduction (single + subset rules) and a
    local-risk ranking instead of giving up.
"""

import sys
from collections import deque

N = 16
TOTAL_MINES = 40  # standard mine count for a 16x16 board


def parse_board(path):
    try:
        with open(path, "r") as f:
            raw_lines = [ln.rstrip("\n") for ln in f]
    except OSError:
        return None
    lines = [ln for ln in raw_lines if ln.strip() != ""]
    if len(lines) != N:
        return None
    board = []
    for ln in lines:
        parts = ln.split()
        if len(parts) == N:
            row = parts
        elif len(parts) == 1 and len(parts[0]) == N:
            row = list(parts[0])
        else:
            return None
        for ch in row:
            if ch == ".":
                continue
            if len(ch) == 1 and ch.isdigit() and 0 <= int(ch) <= 8:
                continue
            return None
        board.append(row)
    if len(board) != N or any(len(r) != N for r in board):
        return None
    return board


def neighbours(r, c):
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc


def fallback_move(board, hidden, constraints):
    """Best-effort safest cell when constraints are globally inconsistent.

    Uses the classic single-constraint + subset-difference deduction to
    fixpoint (mirroring standard local solvers), returning the first
    deduced-safe cell; if none is found, ranks cells by local risk.
    """
    sets = [set(vs) for _, vs in constraints]
    vals = [v for v, _ in constraints]
    n = len(constraints)
    safe = set()
    mine = set()

    for _ in range(200):  # fixpoint iterations (bounded)
        rem = [s - safe - mine for s in sets]
        need = [vals[i] - len(sets[i] & mine) for i in range(n)]
        # sanity: detect direct contradiction (ignored for output purposes)
        changed = False
        for i in range(n):
            if need[i] == 0 and rem[i]:
                new = rem[i] - mine
                if new:
                    safe |= new
                    changed = True
            elif need[i] == len(rem[i]) and rem[i]:
                new = rem[i] - safe
                if new:
                    mine |= new
                    changed = True
        # subset rule on reduced constraints
        rem = [s - safe - mine for s in sets]
        need = [vals[i] - len(sets[i] & mine) for i in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if rem[i] and rem[i] <= rem[j]:
                    diff = rem[j] - rem[i]
                    d = need[j] - need[i]
                    if d == 0 and diff:
                        new = diff - mine
                        if new:
                            safe |= new
                            changed = True
                    elif d == len(diff) and diff:
                        new = diff - safe
                        if new:
                            mine |= new
                            changed = True
        if not changed:
            break

    hidden_set = set(hidden)
    safe_cells = sorted(safe & hidden_set)
    if safe_cells:
        r, c = safe_cells[0]
        return r, c

    # No deduction: rank by local risk = highest adjacent number density
    # (max is the tightest pessimistic bound); background cells meld in.
    density = []
    for v, vs in constraints:
        if vs:
            density.append(v / len(vs))
    bg_risk = sum(density) / len(density) if density else 0.0

    def risk(cell):
        r, c = cell
        loc = [v / len(vs) for v, vs in constraints if cell in set(vs)]
        # ^ sets rebuilt per cell is slow; constraints are small, fine.
        if not loc:
            return bg_risk
        return max(loc)

    best = min(sorted(hidden), key=lambda cell: (risk(cell), cell[0], cell[1]))
    return best[0], best[1]


def solve():
    board = parse_board("/app/board.txt")

    def write(s):
        with open("/app/safe_move.txt", "w") as f:
            f.write(s)

    if board is None:
        write("-1,-1")
        return

    hidden = [(r, c) for r in range(N) for c in range(N) if board[r][c] == "."]
    if not hidden:
        write("-1,-1")
        return

    # Cell-form constraints: (value, [hidden neighbour cells]).
    constraints = []
    for r in range(N):
        for c in range(N):
            if board[r][c] != ".":
                v = int(board[r][c])
                adj = [(nr, nc) for (nr, nc) in neighbours(r, c)
                       if board[nr][nc] == "."]
                if v < 0 or v > len(adj):
                    # Directly self-contradictory number -> invalid board.
                    write("-1,-1")
                    return
                if adj:
                    constraints.append((v, adj))
                elif v != 0:
                    write("-1,-1")
                    return

    frontier_set = set()
    for _, vs in constraints:
        frontier_set.update(vs)
    frontier = sorted(frontier_set)
    background = [cell for cell in hidden if cell not in frontier_set]

    if not frontier:
        r, c = hidden[0]
        write(f"{r},{c}")
        return

    var_index = {v: i for i, v in enumerate(frontier)}
    cons_idx = [(v, [var_index[x] for x in vs]) for v, vs in constraints]

    # Connected components of variables sharing a constraint.
    adj = {i: set() for i in range(len(frontier))}
    for _, vs in cons_idx:
        for a in vs:
            for b in vs:
                if a != b:
                    adj[a].add(b)
    visited = [False] * len(frontier)
    components = []
    for i in range(len(frontier)):
        if visited[i]:
            continue
        q = deque([i])
        visited[i] = True
        comp = {i}
        while q:
            u = q.popleft()
            for w in adj[u]:
                if not visited[w]:
                    visited[w] = True
                    comp.add(w)
                    q.append(w)
        comp_cons = [ci for ci, (_, vs) in enumerate(cons_idx)
                     if any(v in comp for v in vs)]
        components.append((sorted(comp), comp_cons))

    LIMIT_SOLUTIONS = 200000
    prob = {}
    comp_avgs = []
    globally_consistent = True

    for comp_vars, comp_cons in components:
        k = len(comp_vars)
        g2l = {g: li for li, g in enumerate(comp_vars)}
        local_cons = [(v, [g2l[g] for g in vs])
                      for ci in comp_cons for v, vs in [cons_idx[ci]]]
        degree = [0] * k
        for _, vs in local_cons:
            for li in vs:
                degree[li] += 1
        order = sorted(range(k), key=lambda li: -degree[li])
        l2o = {li: oi for oi, li in enumerate(order)}
        o_cons = [(v, [l2o[li] for li in vs]) for v, vs in local_cons]

        if k <= 32:
            assign = [-1] * k
            mine_count = [0] * k
            nsol = 0
            tot_mines = 0
            capped = [False]
            sys.setrecursionlimit(10000)

            def feasible():
                for v, vs in o_cons:
                    s = 0
                    u = 0
                    for oi in vs:
                        a = assign[oi]
                        if a == 1:
                            s += 1
                        elif a == -1:
                            u += 1
                    if s > v or s + u < v:
                        return False
                return True

            def dfs(pos):
                nonlocal nsol, tot_mines
                if capped[0]:
                    return
                if pos == k:
                    nsol += 1
                    tot_mines += sum(assign)
                    for oi in range(k):
                        if assign[oi] == 1:
                            mine_count[oi] += 1
                    if nsol >= LIMIT_SOLUTIONS:
                        capped[0] = True
                    return
                for val in (0, 1):
                    assign[pos] = val
                    if feasible():
                        dfs(pos + 1)
                        if capped[0]:
                            assign[pos] = -1
                            return
                    assign[pos] = -1

            dfs(0)
            if nsol == 0:
                globally_consistent = False
                break
            for oi, li in enumerate(order):
                prob[comp_vars[li]] = mine_count[oi] / nsol
            comp_avgs.append(tot_mines / nsol)
        else:
            # Very large component: estimate by rejection sampling.
            import random
            random.seed(0)
            tot_v = sum(v for v, _ in o_cons)
            tot_slots = sum(len(vs) for _, vs in o_cons)
            p0 = tot_v / tot_slots if tot_slots else 0.2
            p0 = min(max(p0, 0.05), 0.95)
            acc = [0] * k
            tot_m = 0
            valid = 0
            trials = 0
            while valid < 5000 and trials < 200000:
                trials += 1
                a = [1 if random.random() < p0 else 0 for _ in range(k)]
                ok = True
                for v, vs in o_cons:
                    if sum(a[oi] for oi in vs) != v:
                        ok = False
                        break
                if ok:
                    valid += 1
                    tot_m += sum(a)
                    for oi in range(k):
                        acc[oi] += a[oi]
            if valid == 0:
                for oi, li in enumerate(order):
                    s = 0.0
                    cnt = 0
                    for v, vs in o_cons:
                        if oi in vs:
                            s += v / len(vs)
                            cnt += 1
                    prob[comp_vars[li]] = (s / cnt) if cnt else p0
                comp_avgs.append(sum(prob[comp_vars[li]] for li in range(k)))
            else:
                for oi, li in enumerate(order):
                    prob[comp_vars[li]] = acc[oi] / valid
                comp_avgs.append(tot_m / valid)

    if not globally_consistent:
        # Individually plausible but jointly impossible (could never arise
        # from a real game): still return the best-effort safest cell.
        r, c = fallback_move(board, hidden, constraints)
        write(f"{r},{c}")
        return

    for g in sorted(prob):
        if prob[g] == 0.0:
            r, c = frontier[g]
            write(f"{r},{c}")
            return

    min_g = min(prob, key=lambda g: (prob[g], g))
    min_p = prob[min_g]

    if background:
        avg_frontier = sum(comp_avgs)
        if avg_frontier > TOTAL_MINES:
            bg_p = avg_frontier / len(frontier) if frontier else 1.0
        else:
            bg_p = (TOTAL_MINES - avg_frontier) / len(background)
            bg_p = min(max(bg_p, 0.0), 1.0)
        if bg_p <= min_p:
            revealed = [(r, c) for r in range(N) for c in range(N)
                        if board[r][c] != "."]

            def lanci(cell):
                r, c = cell
                if not revealed:
                    return 99
                return min(abs(r - rr) + abs(c - cc) for rr, cc in revealed)

            best = max(background, key=lambda cell: (lanci(cell),
                                                     -cell[0], -cell[1]))
            write(f"{best[0]},{best[1]}")
            return

    r, c = frontier[min_g]
    write(f"{r},{c}")


if __name__ == "__main__":
    solve()
