"""Lean verification for /app/main.py. Restores board.txt on exit."""
import itertools
import random
import subprocess
import sys

N = 16
ORIG = open('/app/board.txt').read()
fails = []


def check(name, cond, info=''):
    print(('PASS' if cond else 'FAIL'), name, info, flush=True)
    if not cond:
        fails.append(name)


def run_solver(board_text):
    with open('/app/board.txt', 'w') as f:
        f.write(board_text)
    p = subprocess.run([sys.executable, '/app/main.py'],
                       capture_output=True, text=True, timeout=60)
    assert p.returncode == 0, p.stderr
    return open('/app/safe_move.txt').read().strip()


def to_text(board):
    return '\n'.join(' '.join(row) for row in board) + '\n'


def parse(text):
    return [ln.split() for ln in text.strip().split('\n')]


def brute(board):
    """Independent exact check via bitmask enumeration. Returns
    (status, prob, background) with status in ok/unsat/invalid-local/big."""
    hidden = [(r, c) for r in range(N) for c in range(N) if board[r][c] == '.']
    masks = []
    vals = []
    for r in range(N):
        for c in range(N):
            if board[r][c] != '.':
                v = int(board[r][c])
                adj = [(r + dr, c + dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                       if not (dr == 0 and dc == 0)
                       and 0 <= r + dr < N and 0 <= c + dc < N
                       and board[r + dr][c + dc] == '.']
                if v < 0 or v > len(adj):
                    return 'invalid-local', {}, []
                if adj:
                    masks.append(adj)
                    vals.append(v)
    front = sorted({x for vs in masks for x in vs})
    if not front:
        return 'ok', {}, list(hidden)
    if len(front) > 20:
        return 'big', {}, []
    idx = {v: i for i, v in enumerate(front)}
    bmasks = []
    for vs in masks:
        m = 0
        for x in vs:
            m |= 1 << idx[x]
        bmasks.append(m)
    n = len(front)
    tot = 0
    mine_ct = [0] * n
    for bits in range(1 << n):
        ok = True
        for m, v in zip(bmasks, vals):
            if bin(bits & m).count('1') != v:
                ok = False
                break
        if ok:
            tot += 1
            for i in range(n):
                if bits >> i & 1:
                    mine_ct[i] += 1
    if tot == 0:
        return 'unsat', {}, []
    prob = {cell: mine_ct[idx[cell]] / tot for cell in front}
    back = [c for c in hidden if c not in set(front)]
    return 'ok', prob, back


def gen_valid_board(seed, mines=40):
    rng = random.Random(seed)
    cells = [(r, c) for r in range(N) for c in range(N)]
    ml = set(rng.sample(cells, mines))
    num = {}
    for r in range(N):
        for c in range(N):
            if (r, c) in ml:
                continue
            num[(r, c)] = sum((r + dr, c + dc) in ml
                              for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                              if not (dr == 0 and dc == 0))
    zeros = [c for c, k in num.items() if k == 0]
    start = rng.choice(zeros)
    revealed, stack = set(), [start]
    while stack:
        cell = stack.pop()
        if cell in revealed or cell in ml:
            continue
        revealed.add(cell)
        if num[cell] == 0:
            r, c = cell
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nb = (r + dr, c + dc)
                    if 0 <= nb[0] < N and 0 <= nb[1] < N:
                        stack.append(nb)
    extra = [c for c in num if c not in revealed and c not in ml]
    revealed |= set(rng.sample(extra, min(len(extra), rng.randint(0, 6))))
    board = [['.'] * N for _ in range(N)]
    for (r, c) in revealed:
        board[r][c] = str(num[(r, c)])
    return board


try:
    out = run_solver(ORIG)
    b = parse(ORIG)
    r, c = map(int, out.split(','))
    check('shipped-format', out.count(',') == 1, out)
    check('shipped-hidden', b[r][c] == '.', out)
    check('shipped-phase1', out == '2,4', out)

    check('malformed', run_solver('hello\n') == '-1,-1')
    check('badchar', run_solver(to_text([['X'] * N for _ in range(N)])) == '-1,-1')
    check('wrongsize', run_solver('. .\n. .\n') == '-1,-1')
    check('nohidden', run_solver(to_text([['0'] * N for _ in range(N)])) == '-1,-1')
    bb2 = [['0'] * N for _ in range(N)]
    bb2[0][0] = '1'
    check('local-impossible', run_solver(to_text(bb2)) == '-1,-1')
    check('empty-board', run_solver(to_text([['.'] * N for _ in range(N)])) == '0,0')

    # handcrafted valid: single '1' top-left corner -> frontier {3 cells}
    # each p=1/3; background lower -> expect background cell, still hidden
    hb = [['.'] * N for _ in range(N)]
    hb[0][0] = '1'
    out = run_solver(to_text(hb))
    r, c = map(int, out.split(','))
    check('corner1-hidden', hb[r][c] == '.', out)
    st, prob, back = brute(hb)
    check('corner1-brute', st == 'ok' and abs(prob[hb and (0, 1)] - 1 / 3) < 1e-9, str(st))
    # background prob = (40-1)/252 < 1/3 -> background expected
    check('corner1-bg', (r, c) in back, out)

    # valid simulated boards
    for seed in range(3):
        board = gen_valid_board(100 + seed)
        out = run_solver(to_text(board))
        r, c = map(int, out.split(','))
        assert board[r][c] == '.', f'seed {seed}: revealed {out}'
        st, prob, back = brute(board)
        if st == 'big':
            print(f'seed {seed}: frontier big, hidden-only check', flush=True)
            continue
        assert st == 'ok', f'seed {seed}: {st}'
        safe = {cell for cell, p in prob.items() if p == 0.0}
        if safe:
            check(f'seed{seed}-safe', (r, c) in safe, f'got {(r, c)}')
        else:
            exp_f = sum(prob.values())
            bg = (40 - exp_f) / len(back) if back else 2.0
            min_p = min(prob.values())
            if bg < min_p - 1e-9:
                check(f'seed{seed}-bg', (r, c) in back, f'got {(r, c)}')
            else:
                check(f'seed{seed}-min', abs(prob[(r, c)] - min_p) < 1e-9,
                      f'got {(r, c)} p={prob[(r, c)]:.3f} min={min_p:.3f}')
    print('fails:', fails, flush=True)
finally:
    with open('/app/board.txt', 'w') as f:
        f.write(ORIG)
    subprocess.run([sys.executable, '/app/main.py'], capture_output=True)
    import shutil
    shutil.rmtree('/app/__pycache__', ignore_errors=True)
