"""Exactness check on small-frontier VALID boards. Restores board.txt."""
import random
import subprocess
import sys

N = 16
ORIG = open('/app/board.txt').read()
fails = []


def check(name, cond, info=''):
    print(('PASS' if cond else 'FAIL'), name, info, flush=True)
    if not cond:
        fails.append(name)


def run_solver(board_text):
    with open('/app/board.txt', 'w') as f:
        f.write(board_text)
    p = subprocess.run([sys.executable, '/app/main.py'],
                       capture_output=True, text=True, timeout=60)
    assert p.returncode == 0, p.stderr
    return open('/app/safe_move.txt').read().strip()


def to_text(board):
    return '\n'.join(' '.join(row) for row in board) + '\n'


def brute(board):
    hidden = [(r, c) for r in range(N) for c in range(N) if board[r][c] == '.']
    masks, vals = [], []
    for r in range(N):
        for c in range(N):
            if board[r][c] != '.':
                v = int(board[r][c])
                adj = [(r + dr, c + dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                       if not (dr == 0 and dc == 0)
                       and 0 <= r + dr < N and 0 <= c + dc < N
                       and board[r + dr][c + dc] == '.']
                if v < 0 or v > len(adj):
                    return 'invalid-local', {}, []
                if adj:
                    masks.append(adj)
                    vals.append(v)
    front = sorted({x for vs in masks for x in vs})
    if not front:
        return 'ok', {}, list(hidden)
    if len(front) > 20:
        return 'big', {}, []
    idx = {v: i for i, v in enumerate(front)}
    bm = []
    for vs in masks:
        m = 0
        for x in vs:
            m |= 1 << idx[x]
        bm.append(m)
    tot, mine_ct = 0, [0] * len(front)
    for bits in range(1 << len(front)):
        if all(bin(bits & m).count('1') == v for m, v in zip(bm, vals)):
            tot += 1
            for i in range(len(front)):
                if bits >> i & 1:
                    mine_ct[i] += 1
    if tot == 0:
        return 'unsat', {}, []
    return 'ok', {cell: mine_ct[idx[cell]] / tot for cell in front}, \
        [c for c in hidden if c not in set(front)]


def sim_small(seed, mines=40, reveal=5):
    rng = random.Random(seed)
    cells = [(r, c) for r in range(N) for c in range(N)]
    ml = set(rng.sample(cells, mines))
    num = {}
    for r in range(N):
        for c in range(N):
            if (r, c) not in ml:
                num[(r, c)] = sum((r + dr, c + dc) in ml
                                  for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                                  if not (dr == 0 and dc == 0))
    safe = [c for c in num]
    rev = rng.sample(safe, reveal)
    board = [['.'] * N for _ in range(N)]
    for (r, c) in rev:
        board[r][c] = str(num[(r, c)])
    return board


try:
    # interior single '1': frontier p=1/8 each < background -> frontier min
    hb = [['.'] * N for _ in range(N)]
    hb[8][8] = '1'
    out = run_solver(to_text(hb))
    st, prob, back = brute(hb)
    check('interior1-brute', st == 'ok' and len(prob) == 8, f'{st} n={len(prob)}')
    r, c = map(int, out.split(','))
    check('interior1-frontier', (r, c) in prob and abs(prob[(r, c)] - 1 / 8) < 1e-9, out)

